import django_filters
from django.db.models import Q
from .models import Book


class BookFilter(django_filters.FilterSet):
    # فیلترهای ساده
    author = django_filters.NumberFilter(field_name="author__id")
    category = django_filters.CharFilter(field_name="categories__slug")
    language = django_filters.CharFilter(lookup_expr="iexact")
    is_featured = django_filters.BooleanFilter()
    is_active = django_filters.BooleanFilter()

    # بازه قیمت
    min_price = django_filters.NumberFilter(field_name="price", lookup_expr="gte")
    max_price = django_filters.NumberFilter(field_name="price", lookup_expr="lte")

    # بازه تاریخ
    published_after = django_filters.DateFilter(
        field_name="published_at", lookup_expr="gte",
    )
    published_before = django_filters.DateFilter(
        field_name="published_at", lookup_expr="lte",
    )

    # فیلترهای سفارشی
    in_stock = django_filters.BooleanFilter(method="filter_in_stock")
    has_discount = django_filters.BooleanFilter(method="filter_has_discount")
    search = django_filters.CharFilter(method="filter_search")

    class Meta:
        model = Book
        fields = []

    def filter_in_stock(self, qs, name, value):
        if value:
            return qs.filter(stock__gt=0)
        return qs.filter(stock=0)

    def filter_has_discount(self, qs, name, value):
        if value:
            return qs.filter(discount_price__isnull=False)
        return qs.filter(Q(discount_price__isnull=True) | Q(discount_price=0))

    def filter_search(self, qs, name, value):
        if not value:
            return qs
        return qs.filter(
            Q(title__icontains=value)
            | Q(isbn__icontains=value)
            | Q(author__full_name__icontains=value)
        ).distinct()

from rest_framework.pagination import (
    PageNumberPagination,
    LimitOffsetPagination,
    CursorPagination,
)
from rest_framework.response import Response


class StandardPagination(PageNumberPagination):
    page_size = 20
    page_size_query_param = "page_size"
    max_page_size = 100


class FlexiblePagination(LimitOffsetPagination):
    default_limit = 20
    max_limit = 100
    limit_query_param = "limit"
    offset_query_param = "offset"


class TimelinePagination(CursorPagination):
    page_size = 25
    ordering = "-created_at"
    cursor_query_param = "cursor"


class EnvelopePagination(PageNumberPagination):
    page_size = 20
    page_size_query_param = "page_size"
    max_page_size = 100

    def get_paginated_response(self, data):
        return Response({
            "meta": {
                "total": self.page.paginator.count,
                "page": self.page.number,
                "pages": self.page.paginator.num_pages,
                "page_size": self.get_page_size(self.request),
            },
            "links": {
                "next": self.get_next_link(),
                "previous": self.get_previous_link(),
            },
            "data": data,
        })

from rest_framework import viewsets
from .models import Book
from .serializers import BookSerializer
from .pagination import (
    StandardPagination, FlexiblePagination,
    TimelinePagination, EnvelopePagination,
)


class BookViewSet(viewsets.ReadOnlyModelViewSet):
    queryset = Book.objects.select_related("author").all()
    serializer_class = BookSerializer
    pagination_class = StandardPagination

    def get_paginator(self):
        mode = self.request.query_params.get("mode", "standard")
        return {
            "standard": StandardPagination,
            "flexible": FlexiblePagination,
            "cursor": TimelinePagination,
            "envelope": EnvelopePagination,
        }.get(mode, StandardPagination)()

import os
import uuid
from django.db import models
from django.db.models.signals import post_delete
from django.dispatch import receiver


def book_cover_path(instance, filename):
    """مسیر ذخیره: books/covers/<uuid>.<ext>"""
    ext = os.path.splitext(filename)[1].lower()
    if ext not in {".jpg", ".jpeg", ".png", ".webp"}:
        ext = ".jpg"
    return f"books/covers/{uuid.uuid4().hex}{ext}"


class Book(models.Model):
    title = models.CharField(max_length=250)
    cover = models.ImageField(upload_to=book_cover_path, blank=True, null=True)
    # ... بقیه فیلدها


@receiver(post_delete, sender=Book)
def delete_cover_on_book_delete(sender, instance, **kwargs):
    if instance.cover:
        instance.cover.delete(save=False)

from django.db import transaction
from rest_framework import serializers
from .models import Gallery, GalleryImage


class GalleryImageSerializer(serializers.ModelSerializer):
    class Meta:
        model = GalleryImage
        fields = ["id", "image", "caption", "order"]
        read_only_fields = ["id"]

    def validate_image(self, value):
        if value.size > 5 * 1024 * 1024:
            raise serializers.ValidationError("حجم تصویر بیش از ۵ مگابایت.")
        if value.content_type not in ("image/jpeg", "image/png", "image/webp"):
            raise serializers.ValidationError("فرمت تصویر پشتیبانی نمی‌شود.")
        return value


class GalleryCreateSerializer(serializers.ModelSerializer):
    images = GalleryImageSerializer(many=True)

    class Meta:
        model = Gallery
        fields = ["id", "title", "images", "created_at"]
        read_only_fields = ["id", "created_at"]

    def validate_images(self, value):
        if not value:
            raise serializers.ValidationError("حداقل یک تصویر الزامی است.")
        if len(value) > 20:
            raise serializers.ValidationError("حداکثر ۲۰ تصویر.")
        return value

    @transaction.atomic
    def create(self, validated_data):
        images_data = validated_data.pop("images")
        owner = self.context["request"].user
        gallery = Gallery.objects.create(owner=owner, **validated_data)
        GalleryImage.objects.bulk_create([
            GalleryImage(gallery=gallery, **img_data)
            for img_data in images_data
        ])
        return gallery

import csv
from io import StringIO
from rest_framework.renderers import BaseRenderer


DANGEROUS_PREFIXES = ("=", "+", "-", "@", "\t", "\r")


def sanitize_csv_value(value):
    """جلوگیری از CSV Injection."""
    if isinstance(value, str) and value.startswith(DANGEROUS_PREFIXES):
        return "'" + value
    return value


class CSVRenderer(BaseRenderer):
    media_type = "text/csv"
    format = "csv"
    charset = "utf-8"

    def render(self, data, accepted_media_type=None, renderer_context=None):
        # اگر پاسخ صفحه‌بندی‌شده است، results را بگیر
        if isinstance(data, dict) and "results" in data:
            data = data["results"]

        if not isinstance(data, list) or not data:
            return ""

        buffer = StringIO()
        buffer.write("\ufeff")   # BOM برای Excel فارسی

        writer = csv.writer(buffer)

        if isinstance(data[0], dict):
            writer.writerow(data[0].keys())
            for row in data:
                writer.writerow([
                    sanitize_csv_value(v) for v in row.values()
                ])

        return buffer.getvalue()
